  6481  GF_Err gf_isom_add_sample_group_info(GF_ISOFile *movie, u32 track, u32 grouping_type, void *data, u32 data_size, Bool is_default, u32 *sampleGroupDescriptionIndex)
  6482  {
  6483          GF_Err e;
  6484          GF_TrackBox *trak;
  6485          GF_DefaultSampleGroupDescriptionEntry *entry=NULL;
  6486          GF_SampleGroupDescriptionBox *sgdesc = NULL;
  6487
  6488          if (sampleGroupDescriptionIndex) *sampleGroupDescriptionIndex = 0;
  6489          e = CanAccessMovie(movie, GF_ISOM_OPEN_WRITE);
  6490          if (e) return e;
  6491
  6492          trak = gf_isom_get_track_from_file(movie, track);
  6493          if (!trak) return GF_BAD_PARAM;
  6494
  6495
  6496          sgdesc = get_sgdp(trak->Media->information->sampleTable, NULL, grouping_type, NULL);
  6497          if (!sgdesc) return GF_OUT_OF_MEM;
  6498
  6499          if (grouping_type==GF_ISOM_SAMPLE_GROUP_OINF) {
  6500                  GF_OperatingPointsInformation *ptr = gf_isom_oinf_new_entry();
  6501                  GF_BitStream *bs=gf_bs_new(data, data_size, GF_BITSTREAM_READ);
  6502                  e = gf_isom_oinf_read_entry(ptr, bs);
  6503                  gf_bs_del(bs);
  6504                  if (e) {
  6505                          gf_isom_oinf_del_entry(ptr);
  6506                          return e;
  6507                  }
  6508                  e = gf_list_add(sgdesc->group_descriptions, ptr);
  6509                  if (e) return e;
  6510                  entry = (GF_DefaultSampleGroupDescriptionEntry *) ptr;
  6511          } else if (grouping_type==GF_ISOM_SAMPLE_GROUP_LINF) {
  6512                  GF_LHVCLayerInformation *ptr = gf_isom_linf_new_entry();
  6513                  GF_BitStream *bs=gf_bs_new(data, data_size, GF_BITSTREAM_READ);
  6514                  e = gf_isom_linf_read_entry(ptr, bs);
  6515                  gf_bs_del(bs);
  6516                  if (e) {
  6517                          gf_isom_linf_del_entry(ptr);
  6518                          return e;
  6519                  }
  6520                  e = gf_list_add(sgdesc->group_descriptions, ptr);
  6521                  if (e) return e;
  6522                  entry = (GF_DefaultSampleGroupDescriptionEntry *) ptr;
  6523          } else {
  6524                  u32 i, count=gf_list_count(sgdesc->group_descriptions);
  6525                  for (i=0; i<count; i++) {
  6526                          GF_DefaultSampleGroupDescriptionEntry *ent = gf_list_get(sgdesc->group_descriptions, i);
  6527                          if ((ent->length == data_size) && !memcmp(ent->data, data, data_size)) {
  6528                                  entry = ent;
  6529                                  break;
  6530                          }
  6531                          entry=NULL;
  6532                  }
  6533                  if (!entry) {
  6534                          GF_SAFEALLOC(entry, GF_DefaultSampleGroupDescriptionEntry);
  6535                          if (!entry) return GF_OUT_OF_MEM;
  6536                          entry->data = (u8*)gf_malloc(sizeof(char) * data_size);
  6537                          if (!entry->data) {
  6538                                  gf_free(entry);
  6539                                  return GF_OUT_OF_MEM;
  6540                          }
  6541                          entry->length = data_size;
  6542                          memcpy(entry->data, data, sizeof(char) * data_size);
  6543                          e = gf_list_add(sgdesc->group_descriptions, entry);
  6544                          if (e) {
  6545                                  gf_free(entry->data);
  6546                                  gf_free(entry);
  6547                                  return e;
  6548                          }
  6549                  }
  6550          }
  6551
  6552
  6553          if (is_default) {
  6554                  sgdesc->default_description_index = 1 + gf_list_find(sgdesc->group_descriptions, entry);
  6555                  sgdesc->version = 2;
  6556          }
  6557          if (sampleGroupDescriptionIndex) *sampleGroupDescriptionIndex = 1 + gf_list_find(sgdesc->group_descriptions, entry);
  6558
  6559          return GF_OK;
  6560  }
