  6574
  6575          if (trak->Media->information->sampleTable->sampleGroupsDescription) {
  6576                  count = gf_list_count(trak->Media->information->sampleTable->sampleGroupsDescription);
  6577                  for (i=0; i<count; i++) {
  6578                          GF_SampleGroupDescriptionBox *sgdesc = (GF_SampleGroupDescriptionBox*)gf_list_get(trak->Media->information->sampleTable->sampleGroupsDescription, i);
