  6580                                  gf_isom_box_del_parent(&trak->Media->information->sampleTable->child_boxes, (GF_Box*)sgdesc);
  6581                                  gf_list_rem(trak->Media->information->sampleTable->sampleGroupsDescription, i);
  6582                                  i--;
  6583                                  count--;
  6584                          }
  6585                  }
  6586          }
  6587          if (trak->Media->information->sampleTable->sampleGroups) {
  6588                  count = gf_list_count(trak->Media->information->sampleTable->sampleGroups);
  6589                  for (i=0; i<count; i++) {
  6590                          GF_SampleGroupBox *sgroup = gf_list_get(trak->Media->information->sampleTable->sampleGroups, i);
  6591                          if (sgroup->grouping_type==grouping_type) {
  6592                                  gf_isom_box_del_parent(&trak->Media->information->sampleTable->child_boxes, (GF_Box*)sgroup);
  6593                                  gf_list_rem(trak->Media->information->sampleTable->sampleGroups, i);
  6594                                  i--;
  6595                                  count--;
  6596                          }
  6597                  }
  6598          }
  6599          return GF_OK;
  6600  }
