  6715          if (entry->key_info_size != with_entry->key_info_size) return GF_FALSE;
  6716
  6717          if (!memcmp(entry->key_info, with_entry->key_info, with_entry->key_info_size))
  6718                  return GF_TRUE;
  6719          return GF_FALSE;
